1	<!DOCTYPE html>
2	<html lang="en">
3	<head>
4	<meta charset="UTF-8">
5	<meta http-equiv="Content-Security-Policy" content="default-src 'none'; connect-src 'none'; base-uri 'none'; form-action 'none'; img-src 'none'; script-src 'nonce-{{nonce}}'; style-src-elem {{cspSource}} 'nonce-{{nonce}}'; style-src-attr 'unsafe-inline'; font-src {{cspSource}}">
6	<meta name="viewport" content="width=device-width, initial-scale=1.0">
7	<title>AIChatRender</title>
8	<link rel="stylesheet" href="{{katexCss}}">
9	<style nonce="{{nonce}}">
10	  html {
11	    font-size: var(--vscode-font-size, 13px);
12	  }
13	  body {
14	    font-family: var(--vscode-font-family, sans-serif);
15	    font-size: 108%;
16	    color: var(--vscode-editor-foreground);
17	    background: var(--vscode-editor-background);
18	    margin: 0;
19	    padding: 0.5em 1em 2em;
20	  }
21	  #status, #notice {
22	    font-style: italic;
23	    opacity: 0.8;
24	    padding: 0.3em 0;
25	  }
26	  #status:empty, #notice:empty { display: none; }
27	  #notice { color: var(--vscode-editorWarning-foreground, #c90); }
28	  #log { padding-right: 3ch; }
29	  article {
30	    margin: 0.8em 0;
31	    padding: 0.2em 0 0.2em 0.8em;
32	    border-left: 2px solid var(--vscode-panel-border, #888);
33	  }
34	  article.user {
35	    border: 2px solid var(--vscode-charts-blue, #47f);
36	    border-radius: 4px;
37	    padding: 0.6em 0.8em;
38	    opacity: 0.85;
39	  }
40	  @keyframes aicr-flash {
41	    from { background: var(--vscode-editor-findMatchHighlightBackground, rgba(255, 200, 0, 0.45)); }
42	    to { background: transparent; }
43	  }
44	  article.flash {
45	    animation: aicr-flash 1.4s ease-out 1;
46	  }
47	  @media (prefers-reduced-motion: reduce) {
48	    article.flash { animation-duration: 0.01s; }
49	  }
50	  article header {
51	    font-size: 0.85em;
52	    opacity: 0.65;
53	    margin-bottom: 0.25em;
54	  }
55	  .message-body { white-space: pre-wrap; overflow-wrap: break-word; }
56	  .math.display { margin: 0.4em 0; overflow-x: auto; }
57	  .katex { font-size: 1.1em; }
58	  .message-body h1, .message-body h2, .message-body h3,
59	  .message-body h4, .message-body h5, .message-body h6 {
60	    margin: 0.7em 0 0.35em;
61	    line-height: 1.25;
62	  }
63	  .message-body h1 { font-size: 1.45em; }
64	  .message-body h2 { font-size: 1.3em; }
65	  .message-body h3 { font-size: 1.18em; }
66	  .message-body h4, .message-body h5, .message-body h6 { font-size: 1.08em; }
67	  .md-paragraph { margin: 0.4em 0; }
68	  .message-body ul, .message-body ol {
69	    margin: 0.4em 0;
70	    padding-left: 1.8em;
71	  }
72	  .message-body li { margin: 0.15em 0; }
73	  .message-body blockquote {
74	    margin: 0.5em 0;
75	    padding: 0.1em 0 0.1em 0.8em;
76	    border-left: 3px solid var(--vscode-textBlockQuote-border, #888);
77	    color: var(--vscode-textBlockQuote-foreground, var(--vscode-foreground));
78	    background: var(--vscode-textBlockQuote-background, transparent);
79	  }
80	  .message-body pre {
81	    overflow-x: auto;
82	    margin: 0.5em 0;
83	    padding: 0.6em 0.8em;
84	    border-radius: 3px;
85	    background: var(--vscode-textCodeBlock-background, rgba(127, 127, 127, 0.12));
86	    white-space: pre-wrap;
87	  }
88	  .message-body code {
89	    padding: 0.05em 0.25em;
90	    border-radius: 3px;
91	    font-family: var(--vscode-editor-font-family, monospace);
92	    background: var(--vscode-textCodeBlock-background, rgba(127, 127, 127, 0.12));
93	  }
94	  .message-body pre code { padding: 0; background: transparent; }
95	  .message-body hr {
96	    height: 1px;
97	    margin: 0.8em 0;
98	    border: 0;
99	    background: var(--vscode-panel-border, #888);
100	  }
101	  #turn-index {
102	    position: fixed;
103	    z-index: 1;
104	    top: 0.6em;
105	    right: 0.6em;
106	    display: flex;
107	    flex-direction: column;
108	    max-height: calc(100vh - 1.2em);
109	    overflow-y: auto;
110	    border: 1px solid var(--vscode-panel-border, #888);
111	    border-radius: 4px;
112	    background: var(--vscode-editorWidget-background, var(--vscode-editor-background));
113	    opacity: 0.65;
114	  }
115	  #turn-index:hover, #turn-index:focus-within { opacity: 1; }
116	  #turn-index:empty { display: none; }
117	  #turn-index button {
118	    min-width: 1.6em;
119	    padding: 0.15em 0.35em;
120	    border: 0;
121	    color: var(--vscode-foreground);
122	    background: transparent;
123	    font: inherit;
124	    font-size: 0.75em;
125	    line-height: 1.2;
126	    cursor: pointer;
127	  }
128	  #turn-index button:hover, #turn-index button:focus {
129	    color: var(--vscode-list-activeSelectionForeground);
130	    background: var(--vscode-list-activeSelectionBackground);
131	    outline: none;
132	  }
133	</style>
134	</head>
135	<body>
136	<div id="status"></div>
137	<div id="notice"></div>
138	<nav id="turn-index" aria-label="User turns"></nav>
139	<main id="log"></main>
140	<script nonce="{{nonce}}" src="{{katexJs}}"></script>
141	<script nonce="{{nonce}}" src="{{copyTexJs}}"></script>
142	<script nonce="{{nonce}}" src="{{markdownJs}}"></script>
143	<script nonce="{{nonce}}">
144	(function () {
145	  'use strict';
146	  var vscodeApi = acquireVsCodeApi();
147	  var log = document.getElementById('log');
148	  var statusEl = document.getElementById('status');
149	  var noticeEl = document.getElementById('notice');
150	  var turnIndexEl = document.getElementById('turn-index');
151	
152	  function validSpan(s) {
153	    if (!s || typeof s !== 'object' || typeof s.s !== 'string') return false;
154	    if (s.t === 'text') return true;
155	    if (s.t === 'math') return s.m === 'inline' || s.m === 'display';
156	    return false;
157	  }
158	  function validEntry(e) {
159	    return !!e && typeof e === 'object'
160	      && (e.role === 'assistant' || e.role === 'user')
161	      && typeof e.key === 'number'
162	      && typeof e.tsDisplay === 'string'
163	      && Array.isArray(e.spans) && e.spans.every(validSpan);
164	  }
165	
166	  function appendInlineText(parent, text) {
167	    var pattern = /(`[^`\n]+`|\*\*[^*\n]+\*\*|__[^_\n]+__|\*[^*\n]+\*)/g;
168	    var from = 0;
169	    var match;
170	    while ((match = pattern.exec(text)) !== null) {
171	      if (match.index > from) parent.appendChild(document.createTextNode(text.slice(from, match.index)));
172	      var source = match[0];
173	      var tag = source[0] === '`'
174	        ? 'code'
175	        : source.slice(0, 2) === '**' || source.slice(0, 2) === '__' ? 'strong' : 'em';
176	      var width = tag === 'em' || tag === 'code' ? 1 : 2;
177	      var inline = document.createElement(tag);
178	      inline.textContent = source.slice(width, -width);
179	      parent.appendChild(inline);
180	      from = pattern.lastIndex;
181	    }
182	    if (from < text.length) parent.appendChild(document.createTextNode(text.slice(from)));
183	  }
184	
185	  function appendMath(parent, span) {
186	    var el = document.createElement(span.m === 'display' ? 'div' : 'span');
187	    el.className = 'math ' + span.m;
188	    try {
189	      katex.render(span.s, el, {
190	        displayMode: span.m === 'display',
191	        throwOnError: false,
192	        trust: false,
193	        maxExpand: 1000,
194	        maxSize: 20
195	      });
196	    } catch (err) {
197	      el.textContent = span.s;
198	    }
199	    parent.appendChild(el);
200	  }
201	
202	  function appendTokens(parent, tokens) {
203	    for (var i = 0; i < tokens.length; i++) {
204	      var token = tokens[i];
205	      if (token.t === 'text') appendInlineText(parent, token.s);
206	      else appendMath(parent, token);
207	    }
208	  }
209	
210	  function appendLines(parent, lines) {
211	    for (var i = 0; i < lines.length; i++) {
212	      if (i > 0) parent.appendChild(document.createElement('br'));
213	      appendTokens(parent, lines[i]);
214	    }
215	  }
216	
217	  function renderMarkdown(parent, spans) {
218	    var blocks = AIChatRenderMarkdown.parse(spans);
219	    for (var i = 0; i < blocks.length; i++) {
220	      var block = blocks[i];
221	      var el;
222	      if (block.type === 'heading') {
223	        el = document.createElement('h' + block.level);
224	        appendTokens(el, block.content);
225	      } else if (block.type === 'list') {
226	        el = document.createElement(block.ordered ? 'ol' : 'ul');
227	        for (var j = 0; j < block.items.length; j++) {
228	          var item = document.createElement('li');
229	          appendTokens(item, block.items[j]);
230	          el.appendChild(item);
231	        }
232	      } else if (block.type === 'blockquote') {
233	        el = document.createElement('blockquote');
234	        appendLines(el, block.lines);
235	      } else if (block.type === 'code') {
236	        el = document.createElement('pre');
237	        var code = document.createElement('code');
238	        code.textContent = block.text;
239	        el.appendChild(code);
240	      } else if (block.type === 'rule') {
241	        el = document.createElement('hr');
242	      } else {
243	        el = document.createElement('div');
244	        el.className = 'md-paragraph';
245	        appendLines(el, block.lines);
246	      }
247	      parent.appendChild(el);
248	    }
249	  }
250	
251	  // Prose is assigned with textContent or text nodes; only math source reaches KaTeX.
252	  function render(msg) {
253	    statusEl.textContent = typeof msg.status === 'string' ? msg.status : '';
254	    noticeEl.textContent = typeof msg.notice === 'string' ? msg.notice : '';
255	    var atBottom = window.innerHeight + window.scrollY >= document.body.scrollHeight - 40;
256	    log.replaceChildren();
257	    turnIndexEl.replaceChildren();
258	    var entries = Array.isArray(msg.entries) ? msg.entries : [];
259	    var turnNumber = 0;
260	    for (var i = 0; i < entries.length; i++) {
261	      var e = entries[i];
262	      if (!validEntry(e)) continue;
263	      var art = document.createElement('article');
264	      art.className = e.role;
265	      art.dataset.key = String(e.key);
266	      if (e.role === 'user') {
267	        turnNumber++;
268	        art.id = 'user-turn-' + turnNumber;
269	        var turnButton = document.createElement('button');
270	        turnButton.type = 'button';
271	        turnButton.textContent = String(turnNumber);
272	        turnButton.title = 'Go to user turn ' + turnNumber;
273	        turnButton.setAttribute('aria-label', turnButton.title);
274	        turnButton.dataset.target = art.id;
275	        turnIndexEl.appendChild(turnButton);
276	      }
