test('markdown: headings retain inline math', () => {
  assert.deepEqual(
    parse([
      { t: 'text', s: '## Result for ' },
      { t: 'math', m: 'inline', s: 'x' },
    ]),
    [
      {
        type: 'heading',
        level: 2,
        content: [
          { t: 'text', s: 'Result for ' },
          { t: 'math', m: 'inline', s: 'x' },
        ],
      },
    ],
  );
});

test('markdown: unordered and ordered outlines form separate lists', () => {
  assert.deepEqual(
    parse([{ t: 'text', s: '- first\n- second\n\n1. one\n2. two' }]),
    [
      {
        type: 'list',
        ordered: false,
        items: [[{ t: 'text', s: 'first' }], [{ t: 'text', s: 'second' }]],
      },
      {
