import json, re, os, glob, sys

PIPE  = re.compile(r'^\s*\|?\s*:?-{2,}:?\s*(\|\s*:?-{2,}:?\s*)+\|?\s*$')
GRID  = re.compile(r'^\s*\+([-=]{3,}\+)+\s*$')
SIMPLE= re.compile(r'^\s*-{2,}(\s+-{2,})+\s*$')

def texts(obj):
    """Yield assistant-authored text from either vendor's record shapes."""
    out = []
    def walk(o, role=None):
        if isinstance(o, dict):
            r = o.get('role') or o.get('type') or role
            if o.get('type') == 'text' and isinstance(o.get('text'), str):
                if role in ('assistant',): out.append(o['text'])
            for k, v in o.items():
                walk(v, r if r in ('assistant','user') else role)
        elif isinstance(o, list):
            for v in o: walk(v, role)
    walk(obj)
    return out

def scan(paths):
    stats = dict(files=0, msgs=0, pipe=0, grid=0, simple=0,
                 files_pipe=0, files_grid=0, files_simple=0, errors=0)
    for p in paths:
        try:
            fp, fg, fs = 0, 0, 0
            with open(p, encoding='utf-8', errors='replace') as fh:
                for ln in fh:
                    try: obj = json.loads(ln)
                    except Exception: continue
                    for t in texts(obj):
                        stats['msgs'] += 1
                        for line in t.split('\n'):
                            if PIPE.match(line) and '|' in line: fp += 1
                            elif GRID.match(line): fg += 1
                            elif SIMPLE.match(line): fs += 1
            stats['files'] += 1
            stats['pipe'] += fp; stats['grid'] += fg; stats['simple'] += fs
            stats['files_pipe'] += fp > 0; stats['files_grid'] += fg > 0
            stats['files_simple'] += fs > 0
        except OSError as e:
            stats['errors'] += 1
    return stats

N = int(sys.argv[1]) if len(sys.argv) > 1 else 120
for vendor in ('claude', 'codex'):
    files = glob.glob(f'/workspace/.tools/ai-sesh/data/*/{vendor}/**/*.jsonl', recursive=True)
    files.sort(key=lambda p: os.path.getmtime(p), reverse=True)
    print(vendor, scan(files[:N]))
