  const body = handler.slice(0, handler.indexOf('}, true);') + '}, true);'.length);
  assert.match(body, /}, true\);$/, 'registered on the capture phase');
  assert.ok(
    body.indexOf("querySelector('table')") < body.indexOf('preventDefault'),
